'use strict';
(function(){
const nav=document.createElement('button');nav.dataset.tab='ab';nav.textContent='⚖ Firebase A/B testing';nav.onclick=()=>tab('ab');document.querySelector('nav').insertBefore(nav,document.querySelector('[data-tab="bq"]'));
const page=document.createElement('section');page.id='ab';page.className='page';page.hidden=true;page.innerHTML=`
<div class="eyebrow">EXPERIMENT INTELLIGENCE • FIREBASE</div><h1>Đo tác động thực.<br><span>Mỗi event là một metric.</span></h1><p class="muted">So sánh variant, kiểm tra biến động và phân đoạn hành vi trong cùng một workspace.</p>
<div class="toolbar"><span id="abSource">Chưa nhập Firebase event log</span><button id="abDemo">✧ Dùng A/B demo</button><button id="abFromQuery">Nhận kết quả BigQuery</button><button id="abExport">↓ Xuất kết quả CSV</button></div>
<article class="card"><div class="cardhead"><h2>01 · Dữ liệu Firebase</h2><span class="tag">EVENT LEVEL</span></div><div class="toolbar"><label class="ab-file">↥ Chọn CSV / JSON / Excel<input id="abFile" type="file" accept=".csv,.tsv,.json,.xlsx,.xls" hidden></label><button id="abFromImport">Dùng file ở Nhập dữ liệu</button><button id="abTemplate">↓ CSV mẫu</button></div><p class="muted">Raw Firebase JSON với user_properties + event_params, CSV đã flatten, hoặc query GA4. Cần event log có toàn bộ user được phân nhóm, kể cả user không phát sinh goal event.</p><details><summary>Mapping cột nâng cao</summary><div id="abMapping" hidden></div></details></article>
<article class="card"><div class="cardhead"><h2>02 · Phạm vi & bộ lọc</h2><button id="abReset">Xóa lọc</button></div><div class="formgrid ab-filters"><label>Experiment<select id="abExperiment"></select></label><label>Baseline<select id="abBaseline"></select></label><label>Exposure từ ngày<input id="abFrom" type="date"></label><label>Exposure đến ngày<input id="abTo" type="date"></label><label>Dữ liệu đầy đủ đến hết ngày<input id="abObservation" type="date"></label><label>Cửa sổ đo từ exposure (ngày)<input id="abWindow" type="number" min="1" max="90" value="7"></label><label>Variant hiển thị<select id="abVariants" multiple></select></label></div><div id="abDimensions" class="formgrid ab-filters"></div><div class="toolbar"><label>Thuộc tính tùy chỉnh tại exposure<select id="abCustomDimension"></select></label><button id="abAddDimension">+ Thêm filter</button></div><p class="muted">Không chọn giá trị = tất cả. Giữ Ctrl/Cmd để chọn nhiều. Ngày exposure và biểu đồ dùng UTC. Exposure = lần đầu membership được thấy trong dữ liệu nhập; hãy lấy đủ lịch sử experiment. Cửa sổ đo cố định giúp cohort mới và cũ có cùng thời gian quan sát.</p></article>
<article class="card"><div class="cardhead"><h2>03 · Metric builder</h2><span class="tag">CUSTOM EVENTS</span></div><div class="formgrid"><label>Tên metric<input id="abMetricName" placeholder="Tutorial conversion"></label><label>Cách tính<select id="abMetricType"><option value="conversion">Conversion: % user có event</option><option value="events">Số event / user được phân nhóm</option><option value="value">Tổng parameter / user được phân nhóm</option><option value="total_events">Tổng số event (mô tả)</option><option value="total_value">Tổng parameter (mô tả)</option><option value="event_average">TB giá trị/event theo user có event</option></select></label><label>Event<select id="abMetricEvent"></select></label><label>Parameter dạng số<select id="abMetricParam"></select></label><label>Hướng kỳ vọng<select id="abDirection"><option value="higher">Càng cao càng tốt</option><option value="lower">Càng thấp càng tốt</option></select></label><label>Điều kiện parameter (tùy chọn)<select id="abConditionKey"></select></label><label>Toán tử<select id="abConditionOp"><option value="eq">Bằng</option><option value="ne">Khác</option><option value="gte">≥</option><option value="lte">≤</option><option value="contains">Chứa</option></select></label><label>Giá trị điều kiện<input id="abConditionValue" placeholder="Ví dụ: 5 hoặc rewarded"></label></div><div class="toolbar"><button id="abAddMetric" class="primary">+ Thêm metric</button><button id="abSaveConfig">↓ Xuất cấu hình</button><label class="ab-file">↥ Nhập cấu hình<input id="abConfigFile" type="file" accept=".json" hidden></label></div><div id="abMetricList"></div><p id="abFormula" class="muted"></p><div class="toolbar"><button id="abAnalyze" class="primary">▶ Phân tích A/B test</button><span id="abDirty" class="muted"></span></div></article>
<div id="abStatus" role="status"></div><div id="abKpis" class="kpis"></div><div id="abResults"></div>
<article class="card"><h2>Cách đọc kết quả</h2><p>Delta = variant − baseline. Lift = delta / |baseline|. Conversion dùng điểm phần trăm cho delta. “So với kỳ trước” dùng cohort exposure trong khoảng liền trước có cùng số ngày và cùng bộ lọc; đây không phải ước lượng tác động nhân quả.</p><p>CI 95% và p-value là xấp xỉ frequentist theo mẫu độc lập ở cấp user, chỉ hiện khi mỗi nhóm có ít nhất 30 user và đủ số conversion/non-conversion. Tổng metric không có CI. Chưa điều chỉnh nhiều metric/variant hoặc theo dõi liên tục; không dùng p-value đơn lẻ để chọn winner. Đây không phải thuật toán kết luận Bayesian của Firebase.</p><p class="muted">Không có user_id / variant không được suy diễn. User đổi variant bị loại. Không phát sinh goal event = 0 cho conversion, count và value/user. Parameter số thiếu/sai bị bỏ qua và có cảnh báo. “TB theo user có event” chỉ đo nhóm phát sinh event, có thể bị selection bias. Có event_id thì deduplicate theo user; thiếu event_id thì giữ từng dòng.</p></article>
<article class="card"><div class="cardhead"><h2>Firebase → BigQuery → A/B workspace</h2><span class="tag">GA4 ADAPTER</span></div><div class="formgrid"><label>Dataset<input id="abDataset" placeholder="my-project.analytics_123456"></label><label>Lấy dữ liệu từ ngày<input id="abSqlFrom" type="date"></label><label>Đến ngày<input id="abSqlTo" type="date"></label></div><div class="toolbar"><button id="abSQL">Tạo query Firebase → SQL editor</button></div><p class="muted">Query giữ tất cả event, event params và experiment properties để không làm mất mẫu số. Chọn khoảng gồm lịch sử exposure, kỳ trước và cửa sổ quan sát. Nếu kết quả BigQuery bị giới hạn, thu hẹp scope rồi chạy lại trước khi phân tích. Giới hạn file: 20 MB / 100.000 event; dữ liệu chỉ ở bộ nhớ tab.</p></article>`;
document.querySelector('main').insertBefore(page,document.querySelector('footer'));
let abData=null,rawData=[],abName='',abDemo=false,abMap={},abWorkbook=null,abMetrics=[],abReport=null,extraDimensions=[];
const chartPanel=document.createElement('article');chartPanel.className='card';chartPanel.id='abChartPanel';chartPanel.innerHTML='<div class="cardhead"><h2>Custom metric · Chart explorer</h2><span class="tag">VARIANT COMPARISON</span></div><div class="formgrid"><label>Metric trên chart<select id="abChartMetric" aria-label="Metric trên chart"></select></label><label>Trục thời gian<select id="abChartMode"><option value="calendar">Ngày phát sinh event</option><option value="cohort">Ngày cohort exposure</option></select></label><label>Chart từ ngày X<input id="abChartFrom" type="date"></label><label>Chart đến ngày Y<input id="abChartTo" type="date"></label></div><div class="toolbar"><button id="abUpdateChart" class="primary">Cập nhật chart</button></div><p id="abChartCaption" class="muted">Nhập dữ liệu hoặc dùng demo, rồi tạo metric để xem biểu đồ.</p><div id="abMainChart"></div><div id="abChartComparison"></div>';page.insertBefore(chartPanel,$('abMapping').closest('article'));
function drawMainChart(){try{if(!abReport||!abData){$('abMainChart').innerHTML='';$('abChartComparison').innerHTML='';return}const index=Number($('abChartMetric').value),res=abReport.results[index];if(!res)return;const c=abReport.config,show=c.variants.length?c.variants:abReport.variants,from=$('abChartFrom').value,to=$('abChartTo').value;if(AB.date(from)===null||AB.date(to)===null||from>to)throw Error('Chọn khoảng ngày X–Y hợp lệ cho chart.');let trends;if($('abChartMode').value==='calendar'){trends=CalendarMetric.series(abData.events,c,res.metric,from,to);$('abChartCaption').textContent=res.metric.name+' · theo ngày phát sinh event. Mẫu số mỗi ngày = user thuộc cohort đã đủ cửa sổ đo và đang trong cửa sổ tại ngày đó. Cùng ngày có thể có user đang ở các tuổi cohort khác nhau.'}else{trends=res.trends.map(t=>({...t,points:t.points.filter(p=>p.date>=from&&p.date<=to)}));$('abChartCaption').textContent=res.metric.name+' · theo ngày cohort exposure. Mỗi cohort có '+c.windowDays+' ngày quan sát; tổng metric trong cửa sổ này, không phải tổng theo ngày lịch.'}const pct=res.metric.type==='conversion';$('abMainChart').innerHTML=MetricCharts.chart(trends.filter(t=>show.includes(t.variant)).map(t=>({name:'Variant '+t.variant,points:t.points.map(p=>({x:p.date,y:p.value,n:p.n}))})),{percent:pct,label:res.metric.name+' từ '+from+' đến '+to});$('abChartComparison').innerHTML='<p class="muted">So sánh toàn bộ cohort đã lọc trong cửa sổ '+c.windowDays+' ngày (độc lập khoảng ngày riêng của chart):</p>'+res.groups.filter(g=>show.includes(g.variant)).map(g=>'<span class="chart-stat"><b>Variant '+esc(g.variant)+'</b> '+display(g.value,pct)+(g.variant===c.baseline?' · baseline':' · lift '+display(g.comparison.lift,true))+'</span>').join('')}catch(e){$('abMainChart').innerHTML='<p class="muted">'+esc(e.message)+'</p>';$('abChartComparison').innerHTML=''}}
function syncMainChart(){const old=$('abChartMetric').value;$('abChartMetric').innerHTML=abMetrics.map((m,i)=>'<option value="'+i+'">'+esc(m.name)+'</option>').join('');if(old!==''&&abMetrics[Number(old)])$('abChartMetric').value=old;if(!$('abChartFrom').value)$('abChartFrom').value=$('abFrom').value;if(!$('abChartTo').value)$('abChartTo').value=$('abObservation').value;drawMainChart()}
$('abChartMetric').onchange=drawMainChart;$('abChartMode').onchange=drawMainChart;$('abChartFrom').onchange=drawMainChart;$('abChartTo').onchange=drawMainChart;$('abUpdateChart').onclick=()=>{if(!abReport)$('abAnalyze').click();else drawMainChart()};
const dimensionNames={country:'Quốc gia',platform:'Platform',version:'App version',source:'Acquisition source',app:'App / bundle ID',device:'Device category'};
const mappingFields={user:'User ID',event:'Event name',time:'Timestamp / event date',experiment:'Experiment (flat)',variant:'Variant (flat)',country:'Country',platform:'Platform',version:'App version',source:'Source',app:'App ID',device:'Device category'};
function status(message){$('abStatus').textContent=message}
function dirty(){abReport=null;drawMainChart();$('abResults').innerHTML='';$('abKpis').innerHTML='';$('abDirty').textContent='Cấu hình thay đổi — bấm Phân tích để cập nhật.'}
function options(values,empty=false){return (empty?'<option value="">Tất cả / không dùng</option>':'')+values.map(v=>'<option value="'+esc(v)+'">'+esc(v||'(trống)')+'</option>').join('')}
function values(key){return [...new Set(abData.events.map(e=>e.dims[key]??''))].sort()}
function selected(el){return [...el.selectedOptions].map(o=>o.value)}
function allKeys(){return [...new Set(abData.events.flatMap(e=>Object.keys(e.params)))].sort()}
function loadRaw(data,name,demo=false){if(!Array.isArray(data))data=data?.events;if(!Array.isArray(data)||!data.length)throw Error('Cần array event hoặc JSON {events: [...]}.');if(data.length>100000)throw Error('Vượt 100.000 event. Thu hẹp export trước khi phân tích.');rawData=data;abName=name;abDemo=demo;abMap={};const keys=[...new Set(data.flatMap(Object.keys))];const guesses={user:['user_pseudo_id','user_id','player_id'],event:['event_name','event'],time:['event_timestamp','event_date','date'],experiment:['experiment_id','experiment'],variant:['variant','variant_id'],country:['country'],platform:['platform'],version:['app_version','version'],source:['source','acquisition_source'],app:['app_id','app'],device:['device_category']};for(const [k,v]of Object.entries(guesses))abMap[k]=v.find(v=>keys.includes(v))||'';const el=$('abMapping');el.hidden=false;el.innerHTML=(abWorkbook?'<label>Excel sheet<select id="abSheet">'+options(abWorkbook.SheetNames)+'</select></label>':'')+'<div class="formgrid">'+Object.entries(mappingFields).map(([k,v])=>'<label>'+v+'<select data-ab-map="'+k+'"><option value="">Tự nhận diện / nested Firebase</option>'+options(keys)+'</select></label>').join('')+'</div><div class="toolbar"><button id="abApply" class="primary">Áp dụng mapping</button></div>';el.querySelectorAll('[data-ab-map]').forEach(e=>{e.value=abMap[e.dataset.abMap];e.onchange=()=>abMap[e.dataset.abMap]=e.value});$('abApply').onclick=()=>{try{applyRaw()}catch(e){status(e.message)}};if(abWorkbook){$('abSheet').value=abWorkbook.current||abWorkbook.SheetNames[0];$('abSheet').onchange=e=>{abWorkbook.current=e.target.value;loadRaw(XLSX.utils.sheet_to_json(abWorkbook.Sheets[e.target.value],{raw:true,defval:''}),name)}}applyRaw();}
function applyRaw(){ $('abChartFrom').value='';$('abChartTo').value='';abData=null;dirty();$('abSource').textContent='Đang kiểm tra · '+abName;const parsed=AB.normalize(rawData,abMap);extraDimensions=[];const experiments=[...new Set(parsed.events.flatMap(e=>e.memberships.map(m=>m[0])))].sort();if(!experiments.length)throw Error('Không có membership. Map experiment + variant hoặc nhập user_properties có firebase_exp_XX.');abData=parsed;$('abExperiment').innerHTML=options(experiments);$('abSource').textContent=(abDemo?'● DEMO · ':'● FIREBASE · ')+abName+' · '+abData.events.length+' event';let dates=abData.events.map(e=>e.date).sort();$('abObservation').value=dates.at(-1);$('abFrom').value=dates[0];$('abTo').value=dates.at(-1);$('abSqlFrom').value=dates[0];$('abSqlTo').value=dates.at(-1);$('abMetricEvent').innerHTML=options(['*',...[...new Set(abData.events.map(e=>e.event))].sort()]);const keys=allKeys();$('abMetricParam').innerHTML='<option value="">Chọn parameter</option>'+options(keys);$('abConditionKey').innerHTML=options(keys,true);$('abMetricEvent').value=abData.events.some(e=>e.event==='tutorial_complete')?'tutorial_complete':abData.events[0].event;const numericKeys=keys.filter(k=>abData.events.some(e=>e.params[k]!==''&&e.params[k]!=null&&Number.isFinite(Number(e.params[k]))));$('abMetricParam').value=numericKeys.includes('value')?'value':numericKeys[0]||'';abMetrics=[{id:'starter',name:'Conversion · '+$('abMetricEvent').value,type:'conversion',event:$('abMetricEvent').value,param:'',direction:'higher',conditionKey:'',conditionOp:'eq',conditionValue:''}];renderMetrics();experimentChanged();status('Đã đọc dữ liệu. '+abData.issues.invalid+' dòng lỗi · '+abData.issues.unassigned+' event không có membership (vẫn dùng nếu gắn được với user đã exposure).');dirty();}
function experimentChanged(){if(!abData)return;const exp=$('abExperiment').value,variants=[...new Set(abData.events.flatMap(e=>e.memberships.filter(m=>m[0]===exp).map(m=>m[1])))].sort();$('abBaseline').innerHTML=options(variants);$('abBaseline').value=variants.includes('0')?'0':variants[0];$('abVariants').innerHTML=options(variants);renderDimensions();dirty()}
function renderDimensions(){if(!abData)return;const keys=[...Object.keys(dimensionNames),...extraDimensions];$('abDimensions').innerHTML=keys.map(k=>'<label>'+esc(dimensionNames[k]||k)+'<select multiple data-ab-dim="'+esc(k)+'">'+options(values(k))+'</select></label>').join('');$('abDimensions').querySelectorAll('select').forEach(el=>el.onchange=dirty);const available=[...new Set(abData.events.flatMap(e=>Object.keys(e.dims)))].filter(k=>!keys.includes(k));$('abCustomDimension').innerHTML=options(available,true)}
function formula(m){const condition=m.conditionKey?' với '+m.conditionKey+' '+m.conditionOp+' '+m.conditionValue:'';const goal=m.event==='*'?'bất kỳ event':m.event;const formulas={conversion:'100 × user có '+goal+condition+' / user đủ cửa sổ đo',events:'Số '+goal+condition+' / user đủ cửa sổ đo',value:'Tổng '+m.param+' của '+goal+condition+' / user đủ cửa sổ đo',total_events:'Tổng '+goal+condition,total_value:'Tổng '+m.param+' của '+goal+condition,event_average:'Trung bình các mean '+m.param+' theo từng user có '+goal+condition};return formulas[m.type]}
function renderMetrics(){$('abMetricList').innerHTML=abMetrics.map((m,i)=>'<div class="ab-metric"><div><b>'+esc(m.name)+'</b><p class="muted">'+esc(formula(m))+' · '+(m.direction==='higher'?'↑ cao tốt':'↓ thấp tốt')+'</p></div><button data-remove-metric="'+i+'" aria-label="Xóa '+esc(m.name)+'">×</button></div>').join('');$('abMetricList').querySelectorAll('button').forEach(el=>el.onclick=()=>{abMetrics.splice(+el.dataset.removeMetric,1);renderMetrics();dirty()})}
function builder(){return {id:'m'+Date.now(),name:$('abMetricName').value.trim()||$('abMetricType').selectedOptions[0].text+' · '+$('abMetricEvent').value,type:$('abMetricType').value,event:$('abMetricEvent').value,param:$('abMetricParam').value,direction:$('abDirection').value,conditionKey:$('abConditionKey').value,conditionOp:$('abConditionOp').value,conditionValue:$('abConditionValue').value}}
function validateMetric(m){if(!m.name||m.name.length>150||!['conversion','events','value','total_events','total_value','event_average'].includes(m.type)||!m.event)throw Error('Metric chưa hợp lệ.');if(['value','total_value','event_average'].includes(m.type)&&!m.param)throw Error('Chọn parameter số để tính metric.');if(m.conditionKey&&['gte','lte'].includes(m.conditionOp)&&(!Number.isFinite(Number(m.conditionValue))||m.conditionValue===''))throw Error('Điều kiện ≥/≤ cần giá trị số.');if(!['higher','lower'].includes(m.direction))throw Error('Hướng metric không hợp lệ.');}
$('abAddMetric').onclick=()=>{try{if(!abData)throw Error('Nhập event log trước.');if(abMetrics.length>=12)throw Error('Tối đa 12 metric/lần phân tích.');const m=builder();validateMetric(m);abMetrics.push(m);renderMetrics();dirty();$('abMetricName').value='';$('abChartMetric').innerHTML=abMetrics.map((metric,i)=>'<option value="'+i+'">'+esc(metric.name)+'</option>').join('');$('abChartMetric').value=String(abMetrics.length-1);$('abAnalyze').click()}catch(e){status(e.message)}};
function config(){const filters=Object.fromEntries([...$('abDimensions').querySelectorAll('select')].map(el=>[el.dataset.abDim,selected(el)]));return {experiment:$('abExperiment').value,baseline:$('abBaseline').value,from:$('abFrom').value,to:$('abTo').value,observation:$('abObservation').value,windowDays:Number($('abWindow').value),filters,variants:selected($('abVariants'))}}
function display(v,pct=false){return v===null?'—':fmt(v)+(pct?'%':'')}
function signed(v){return v===null?'—':(v>0?'+':'')+fmt(v)}
const colors=['#148a70','#6375e1','#e6a042','#d66c9c','#4d9cb2','#96785e'];
function trendChart(trends,pct){const dates=[...new Set(trends.flatMap(t=>t.points.map(p=>p.date)))].sort(),vals=trends.flatMap(t=>t.points.filter(p=>p.value!==null).map(p=>p.value));if(!vals.length)return '<p class="muted">Chưa có cohort đủ cửa sổ đo.</p>';let min=Math.min(0,...vals),max=Math.max(0,...vals);if(max===min)max=min+1;const x=d=>60+dates.indexOf(d)/Math.max(1,dates.length-1)*610,y=v=>185-(v-min)/(max-min)*165;let html='<svg viewBox="0 0 700 230" role="img" aria-label="Metric theo ngày exposure và variant">';for(let i=0;i<5;i++){const v=min+(max-min)*i/4;html+='<line x1="60" x2="675" y1="'+y(v)+'" y2="'+y(v)+'" stroke="#eef0f3"/><text x="0" y="'+(y(v)+4)+'">'+fmt(v)+(pct?'%':'')+'</text>'}trends.forEach((t,i)=>{const valid=t.points.filter(p=>p.value!==null);html+='<polyline fill="none" stroke="'+colors[i%colors.length]+'" stroke-width="2.5" points="'+valid.map(p=>x(p.date)+','+y(p.value)).join(' ')+'"/>';valid.forEach(p=>html+='<circle cx="'+x(p.date)+'" cy="'+y(p.value)+'" r="3" fill="'+colors[i%colors.length]+'"><title>'+esc(t.variant)+' · '+p.date+': '+fmt(p.value)+' · n='+p.n+'</title></circle>')});[...new Set([0,Math.floor((dates.length-1)/2),dates.length-1])].forEach(i=>html+='<text x="'+x(dates[i])+'" y="218" text-anchor="'+(i===0?'start':i===dates.length-1?'end':'middle')+'">'+dates[i]+'</text>');return html+'</svg><div class="ab-legend">'+trends.map((t,i)=>'<span><i style="background:'+colors[i%colors.length]+'"></i>Variant '+esc(t.variant)+'</span>').join('')+'</div>'}
function renderReport(r,c){syncMainChart();$('abKpis').innerHTML=[['User exposure trong kỳ',r.inRange,'Trước lọc cửa sổ trưởng thành'],['User đủ cửa sổ đo',r.eligible,c.windowDays+' ngày từ exposure'],['Cohort chưa đủ ngày',r.immature,'Loại khỏi mẫu số'],['User đổi variant',r.switches,'Loại khỏi experiment']].map(([h,n,p])=>'<div class="kpi"><small>'+esc(h)+'</small><strong>'+fmt(n)+'</strong><div class="change">'+esc(p)+'</div></div>').join('');const show=c.variants.length?c.variants:r.variants;$('abResults').innerHTML=r.results.map((res,index)=>{const pct=res.metric.type==='conversion',groups=res.groups.filter(g=>show.includes(g.variant));let max=Math.max(1,...groups.map(g=>Math.abs(g.value||0)));return '<article class="card"><div class="cardhead"><div><h2>'+esc(res.metric.name)+'</h2><p>'+esc(formula(res.metric))+'</p></div><span class="tag">BASELINE '+esc(c.baseline)+'</span></div><div class="ab-bars">'+groups.map((g,i)=>'<div class="barrow"><span>Variant '+esc(g.variant)+' · n='+g.users+'</span><div class="track"><div class="fill" style="background:'+colors[i%colors.length]+';width:'+Math.abs(g.value||0)/max*100+'%"></div></div><b>'+display(g.value,pct)+'</b></div>').join('')+'</div><div class="tablewrap"><table><thead><tr><th>Variant</th><th>User đủ ngày</th><th>User có giá trị</th><th>Metric</th><th>Δ vs baseline'+(pct?' (pp)':'')+'</th><th>Lift %</th><th>CI 95% của Δ</th><th>p (xấp xỉ)</th><th>Chiều tác động</th><th>Kỳ trước</th><th>Δ kỳ trước'+(pct?' (pp)':'')+'</th><th>% kỳ trước</th></tr></thead><tbody>'+groups.map(g=>{const b=g.variant===c.baseline,d=g.comparison.delta,good=d!==null&&(res.metric.direction==='lower'?d<0:d>0),signal=g.comparison.ci&&(g.comparison.ci[0]>0||g.comparison.ci[1]<0);return '<tr><td>'+esc(g.variant)+(b?' · baseline':'')+'</td><td>'+g.users+'</td><td>'+g.n+'</td><td>'+display(g.value,pct)+'</td><td>'+(!b?signed(d):'—')+'</td><td>'+(!b?display(g.comparison.lift,true):'—')+'</td><td>'+(!b&&g.comparison.ci?g.comparison.ci.map(v=>fmt(v)).join(' → '):'—')+'</td><td>'+(!b&&g.comparison.p!==null?g.comparison.p.toFixed(4):'—')+'</td><td>'+(b?'Baseline':d===null?'Thiếu mẫu':d===0?'Không đổi':(good?'Thuận':'Ngược')+' kỳ vọng'+(signal?' · có tín hiệu':' · chưa chắc chắn'))+'</td><td>'+display(g.previous,pct)+'</td><td>'+signed(g.periodDelta)+'</td><td>'+display(g.periodLift,true)+'</td></tr>'}).join('')+'</tbody></table></div><div class="cardhead ab-trend-title"><h2>Metric theo ngày exposure</h2><span class="muted">Mỗi cohort có cùng '+c.windowDays+' ngày quan sát</span></div>'+trendChart(res.trends.filter(t=>show.includes(t.variant)),pct)+'<p class="muted">Kỳ trước: '+r.previousFrom+' → '+r.previousTo+' · '+r.prior+' user đủ ngày. '+res.invalid+' event có parameter số thiếu/sai. Tổng giá trị phản ánh cả quy mô nhóm; dùng value/user để so tác động. Nhiều phép so sánh chưa được điều chỉnh.</p></article>'}).join('');$('abDirty').textContent='Kết quả đã cập nhật.';status((abDemo?'DEMO · ':'')+'Đã phân tích '+c.experiment+' với '+abMetrics.length+' metric. '+(r.eligible===0?'Không có cohort đủ cửa sổ đo.':'')+(r.variants.length<2?' Cần ít nhất 2 variant để so sánh A/B.':''))}
$('abAnalyze').onclick=()=>{try{if(!abData)throw Error('Nhập event log hoặc dùng demo.');if(!abMetrics.length)throw Error('Thêm ít nhất một metric.');abMetrics.forEach(validateMetric);const c=config();if(!c.baseline)throw Error('Chọn baseline.');const r=AB.analyze(abData.events,c,abMetrics);abReport={...r,config:c};renderReport(r,c)}catch(e){status(e.message)}};
$('abExperiment').onchange=experimentChanged;['abBaseline','abFrom','abTo','abObservation','abWindow','abVariants'].forEach(id=>$(id).onchange=dirty);
$('abReset').onclick=()=>{extraDimensions=[];renderDimensions();$('abVariants').selectedIndex=-1;dirty()};$('abAddDimension').onclick=()=>{const key=$('abCustomDimension').value;if(key&&!extraDimensions.includes(key)){const prior=config().filters;extraDimensions.push(key);renderDimensions();$('abDimensions').querySelectorAll('select').forEach(el=>[...el.options].forEach(o=>o.selected=prior[el.dataset.abDim]?.includes(o.value)||false));dirty()}};
async function fileRead(file){if(!file)return;if(file.size>20*1024*1024)throw Error('File vượt 20 MB.');abWorkbook=null;if(/\.xlsx?$/i.test(file.name)){abWorkbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});return XLSX.utils.sheet_to_json(abWorkbook.Sheets[abWorkbook.SheetNames[0]],{defval:'',raw:true})}return /\.json$/i.test(file.name)?JSON.parse(await file.text()):csvParse(await file.text())}
$('abFile').onchange=async e=>{try{const file=e.target.files[0];if(file)loadRaw(await fileRead(file),file.name)}catch(e){status(e.message)}e.target.value=''};
$('abFromImport').onclick=()=>{try{abWorkbook=null;loadRaw(rows,filename,demo)}catch(e){status(e.message)}};
$('abFromQuery').onclick=()=>{try{if(!queryRows.length)throw Error('Chạy query Firebase trong BigQuery studio trước.');if($('queryStatus').textContent.includes('KẾT QUẢ BỊ GIỚI HẠN'))throw Error('Query bị cắt bớt: hãy thu hẹp scope và chạy lại để đảm bảo mẫu số.');abWorkbook=null;loadRaw(queryRows,'BigQuery Firebase')}catch(e){status(e.message)}};
$('abSaveConfig').onclick=()=>download('ab-metrics-config.json',JSON.stringify({version:1,metrics:abMetrics,config:abData?config():null},null,2),'application/json');
$('abConfigFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('Config vượt 100 KB.');const v=JSON.parse(await file.text());if(v.version!==1||!Array.isArray(v.metrics)||!v.metrics.length||v.metrics.length>12)throw Error('Config version/metrics chưa hợp lệ.');v.metrics.forEach(validateMetric);abMetrics=v.metrics;renderMetrics();if(v.config&&abData){const c=v.config;if([...$('abExperiment').options].some(o=>o.value===c.experiment)){$('abExperiment').value=c.experiment;experimentChanged()}for(const [key,id]of Object.entries({baseline:'abBaseline',from:'abFrom',to:'abTo',observation:'abObservation',windowDays:'abWindow'}))if(c[key]!=null)$(id).value=c[key];extraDimensions=Object.keys(c.filters||{}).filter(k=>!dimensionNames[k]&&abData.events.some(e=>k in e.dims));renderDimensions();$('abDimensions').querySelectorAll('select').forEach(el=>[...el.options].forEach(o=>o.selected=!!c.filters?.[el.dataset.abDim]?.includes(o.value)));[...$('abVariants').options].forEach(o=>o.selected=!!c.variants?.includes(o.value))}dirty();status('Đã nhập cấu hình; kiểm tra event và parameter có tồn tại trong dataset.')}catch(err){status(err.message)}e.target.value=''};
$('abExport').onclick=()=>{if(!abReport){status('Phân tích trước khi xuất kết quả.');return}const c=abReport.config;const data=abReport.results.flatMap(r=>r.groups.map(g=>({experiment:c.experiment,baseline:c.baseline,exposure_from:c.from,exposure_to:c.to,observation_until:c.observation,window_days:c.windowDays,filters:JSON.stringify(c.filters),metric:r.metric.name,formula:formula(r.metric),variant:g.variant,eligible_users:g.users,metric_users:g.n,value:g.value,delta:g.comparison.delta,lift_pct:g.comparison.lift,ci_low:g.comparison.ci?.[0]??null,ci_high:g.comparison.ci?.[1]??null,p_approx:g.comparison.p,previous_value:g.previous,previous_delta:g.periodDelta,previous_lift_pct:g.periodLift})));const keys=Object.keys(data[0]);const cell=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';download('ab-test-analysis.csv','\uFEFF'+[keys.map(cell).join(','),...data.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),'text/csv')};
$('abSQL').onclick=()=>{try{$('sql').value=AB.firebaseSQL($('abDataset').value.trim(),$('abSqlFrom').value,$('abSqlTo').value);tab('bq');notify('Đã tạo query Firebase. Chạy hoặc dry run, sau đó trở lại A/B → Nhận kết quả BigQuery.')}catch(e){status(e.message)}};
$('abTemplate').onclick=()=>download('firebase-ab-events.csv','user_id,event_date,event_name,experiment_id,variant,country,platform,app_version,value,level\nu1,2026-09-01,session_start,01,0,Vietnam,ANDROID,1.0,0,1\nu1,2026-09-02,tutorial_complete,01,0,Vietnam,ANDROID,1.0,0,2\nu2,2026-09-01,session_start,01,1,Vietnam,ANDROID,1.0,0,1\nu2,2026-09-02,in_app_purchase,01,1,Vietnam,ANDROID,1.0,4.99,3\nu3,2026-09-15,session_start,01,0,United States,IOS,1.1,0,1','text/csv');
function makeDemo(){const data=[];let seed=912;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let i=0;i<900;i++){const variant=String(i%3),start=Date.UTC(2026,8,1+i%30,8),user='ab_user_'+i,country=i%4?'Vietnam':'United States',platform=i%2?'ANDROID':'IOS';const event=(name,time,params=[])=>data.push({user_pseudo_id:user,event_timestamp:String(time*1000),event_name:name,event_params:params,user_properties:[{key:'firebase_exp_01',value:{string_value:variant}},{key:'plan',value:{string_value:i%3?'free':'premium'}}],geo:{country},platform,app_info:{id:'com.demo.puzzle',version:i%5?'1.3.0':'1.4.0'},device:{category:'mobile'},traffic_source:{source:i%4?'organic':'google_ads'}});event('session_start',start);if(rand()<[.48,.61,.53][+variant])event('tutorial_complete',start+3600000,[{key:'level',value:{int_value:3}}]);for(let d=1;d<7;d++){if(rand()<.55)event('level_complete',start+d*864e5,[{key:'level',value:{int_value:d+3}},{key:'duration',value:{double_value:rand()*50+20}}]);if(rand()<[.08,.12,.1][+variant])event('in_app_purchase',start+d*864e5,[{key:'value',value:{double_value:Math.round((rand()*5+1)*100)/100}},{key:'currency',value:{string_value:'USD'}}])}}abWorkbook=null;loadRaw(data,'Firebase A/B · Onboarding experiment',true);$('abFrom').value='2026-09-16';$('abTo').value='2026-09-30';$('abObservation').value='2026-10-07';abMetrics=[{id:'demo1',name:'Tutorial conversion',type:'conversion',event:'tutorial_complete',param:'',direction:'higher',conditionKey:'',conditionOp:'eq',conditionValue:''},{id:'demo2',name:'IAP value / user (USD)',type:'value',event:'in_app_purchase',param:'value',direction:'higher',conditionKey:'',conditionOp:'eq',conditionValue:''},{id:'demo3',name:'Level complete / user',type:'events',event:'level_complete',param:'',direction:'higher',conditionKey:'level',conditionOp:'gte',conditionValue:'5'}];renderMetrics();$('abAnalyze').click()}
$('abDemo').onclick=()=>{try{makeDemo()}catch(e){status(e.message)}};
['abMetricType','abMetricEvent','abMetricParam','abConditionKey','abConditionOp','abConditionValue'].forEach(id=>$(id).addEventListener('change',()=>{$('abFormula').textContent=formula(builder())}));
})();




